// Morda Café – Asset Loader
const MORDA_LOGO  = 'data:image/png;base64,';
const MORDA_OWNER = 'data:image/png;base64,';
document.addEventListener('DOMContentLoaded',()=>{
  document.querySelectorAll('.site-logo').forEach(el=>el.src=MORDA_LOGO);
  document.querySelectorAll('.owner-photo').forEach(el=>el.src=MORDA_OWNER);
});
